def min_jump_time():
    n, s, e = map(int, input().split())
    x = list(map(int, input().split()))
    a = list(map(int, input().split()))
    b = list(map(int, input().split()))
    c = list(map(int, input().split()))
    d = list(map(int, input().split()))

    dp = [[[sys.maxsize for _ in range(2)] for _ in range(n)] for _ in range(n+1)]

    for i in range(1, n+1):
        for j in range(2):
            dp[i][j][i-1] = abs(x[i-1] - x[s-1]) + (c if j == 0 else d)
            if i < n:
                dp[i][j][i] = abs(x[i] - x[i-1]) + b[i-1] + dp[i-1][j][i-1]

    for i in range(n-2, -1, -1):
        for j in range(2):
            if i == n:
                sorted_x = sorted(x[:n])
            else:
                arr = sorted([a[i], b[n-1-i], d[i]])
                sorted_x = [sorted_x[0]] + [sorted_x[i if arr[i] < arr[0] else i+1] for i in range(n-1)]

            for k in range(n):
                if dp[i][j][k] == sys.maxsize:
                    continue
                for j2 in range(2):
                    dp[i][j2][k+1] = min(dp[i][j2][k+1], dp[i][j][k] + abs(x[k] - x[i+1]) + (c if j2 == 0 else d))
