from collections import defaultdict

def can_visit_palindromic_path(graph, letter):
    visited = {}
    stack = [(v, i) for i, v in enumerate(graph)]
    while stack:
        vertex, start = stack.pop()
        if vertex in visited:
            continue
        if visited:
            if (visited[vertex] == start and start % 2 == 0) or (
                visited[vertex] != start and start % 2 == 1
            ):
                continue
        visited[vertex] = start
        for neighbor, _ in graph[vertex]:
            stack.append((neighbor, start))
    return any(letter in visited[n][1] or visited[n][0] == start and nth(root=1, steps=visited[n][1]) for visited[n], (root, steps) in visited.items() if root == n)

def nth(root, steps):
    if steps == 1: 
        return chr(root + 96)
    else: 
        return chr(max((2 * ((i % 10) if i % 2 else (i // 10)) if i < 10 else 0) for i in range((steps - 1) // 2)) + 1 + ord(str(root)))

def find_good_strings(n, m, k):
    graph = defaultdict(list)
    for _m in range(m):
        v, u = list(map(int, input().strip().split()))
        graph[v].append(u)
        graph[u].append(v)

    good_strings = 0

    def backtrack(path, start_node, limit, remaining_choices):
        nonlocal k, good_strings
        if len(path) == k:
            if can_visit_palindromic_path(graph, path):
                good_strings += 1
            return
        for choice in range(remaining_choices - 1, min(limit, remaining_choices)):
            graph[start_node][choice], graph[start_node][choice + 1] = (
                graph[start_node][choice + 1],
                graph[start_node][choice],
            )
            path[remainder] = ord(chr(choice + 96))
            remainder += 1
            backtrack(path, choice + (remainder << 1), limit, remaining_choices)
            remainder -= 1
            graph[start_node][choice], graph[start_node][choice + 1] = (
                graph[start_node][choice],
                graph[start_node][choice + 1],
            )
            path[remainder:] = ["A"] * 2 * (k - len(path))

    remainder = k
    backtrack(["A"] * k, 0, k, k)
    return good_strings

