from collections import defaultdict

def is_palindrome(s):
    return s == s[::-1]

def is_valid_path(u, v):
    return not is_palindrome(u + v)

def nodes_to_characters(n):
    return range(1, n+1)

def hamiltonian_paths(n, m):
    graph = defaultdict(list)
    for i in range(m):
        u, v = map(int, input().split())
        graph[u].append(v)
        graph[v].append(u)

    n_vertices = n + 1
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    for u in reversed(nodes_to_characters(n)):
        for k in range(1, n + 1):
            for i in range(min(k, u), n + 1):
                if is_valid_path(u, i):
                    dp[i][u] = 0
                for j in range(1, n + 1):
                    if is_palindrome(graph[k-1][i-1] * j):
                        dp[i][u] += dp[k-1][j]
                    if k > 1 and graph[k-2][i-1] == j:
                        dp[i][u] += dp[k-2][j]
            dp[i][u] %= (10**9 + 7)

    return sum(dp[n][i] for i in nodes_to_characters(n))
