from typing import List, Tuple
from heapq import heappush, heappop

def find_kth_prime_number(distinct_primes: List[int], k: int) -> int:
    def prime_numbers_query(size: int) -> int:
        heapq = []
        for prime in distinct_primes:
            if len(heapq) >= size:
                heappush(heapq, -prime)
                smallest_prime = -heapq[0]
            else:
                heappush(heapq, -prime)
                smallest_prime = largest_prime = None

            if smallest_prime is None:
                smallest_prime = smallest_prime or 1
            largest_prime = largest_prime or prime

            # If k is within the range of the last prime kept in the heap
            if smallest_prime + (size - len(heapq)) * 2 < k < largest_prime - (size - len(heapq)) * 2:
                return smallest_prime + (k - smallest_prime) % (largest_prime - smallest_prime)

            # If k is less than the smallest prime not in the heap
            elif k < smallest_prime:
                if size > 1:
                    return k * size
            # If k is more than the largest_prime
            elif k > largest_prime:
                return prime * (k - largest_prime)

    return prime_numbers_query(k)

