import sys

def settle_billiard_ball(n, m, x, y, vx, vy):
    if vx == 0 and vy == 0:
        return (x, y)

    # Check for vertical sides
    if n % 2 == 0 and x <= n // 2:
        return (x, y + 1 if m % 2 == 0 else y - (m - 1))

    # Check for horizontal sides
    if m % 2 == 0 and y <= m // 2:
        return (x, y + 1 if n % 2 == 0 else y - (n - 1))

    # Check for 45-degree angles
    x2 = n // abs(v_y)
    y2 = m // abs(v_x)

    # If the ball goes in the same direction as it came, it will hit a side
    if (x2 == x and m % 2 == 0 and y == y2) or \
       (y2 == y and n % 2 == 0 and x == x2):
        return (-1)

    # Otherwise, we need to check if it will stick to a side
    if x == x2 or y == y2:
        return (-1)

    sx = min(x, x2)
    sy = min(y, y2)
    ex = max(x, x2)
    ey = max(y, y2)

    if n % 2 and sy >= x or m % 2 and sx >= y:
        return (-1)

    return (sy, ey)

