def prime_factor_composition(n, primes):
    for prime in primes:
        if prime > n:
            return -1
        while n % prime == 0:
            n //= prime
    return n

def find_kth_smallest_number(k, primes):
    primes.sort()
    number = 1
    for prime in primes:
        while prime_factor_composition(number, primes) <= k:
            number *= prime
            k -= prime_factor_composition(number, primes)
    return number

