        return a
    return gcd(b, a % b)

def prime_factors(n):
    i = 2
    factors = []
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            factors.append(i)
    if n > 1:
        factors.append(n)
    return factors

def countIntegers(A, B, L, R):
    ans = 0
    coprimesA, coprimesB = defaultdict(set), defaultdict(set)

    for x in range(1, 10 ** 9 + 1):
        if A % x == 0 and B % x == 0:
            ans += 1
        elif gcd(A, x) == 1 and gcd(B, x) == 1:
            coprimesA[x].add(A)
            coprimesB[x].add(B)
        else:
            for factor in prime_factors(A):
                if factor in coprimesA:
                    coprimesB[factor] = coprimesB.get(factor, set()).union(coprimesA[factor])
            for factor in prime_factors(B):
                if factor in coprimesB:
                    coprimesA[factor] = coprimesA.get(factor, set()).union(coprimesB[factor])

    count = 0
    while L <= R:
        for factor in coprimesA:
            for x in coprimesA[factor]:
                if x <= R:
                    count += 1
                    break
        for factor in coprimesB:
            for x in coprimesB[factor]:
                if x <= R:
                    count += 1
                    break
        L = max(L, L + 1)
        if L <= R:
            count += 1
        L = max(L, L + 1)

    return count

