import random

def generate_primes_in_range(start, end):
    if start > end:
        raise ValueError("Start must be less than or equal to end")

    primes = []
    current = start
    while current <= end:
        is_prime = True
        for i in range(2, int(current**0.5) + 1):
            if current % i == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(current)
        current += 1

    return primes

def find_prime_and_r(p, n=10**5, m=2, max_r=10**4):
    prime_list = generate_primes_in_range(m, min(10**9, p))

    for prime in prime_list:
        if p % prime == 0 and prime**2 < p:
            yield prime, power(x, prime, p)

        for r in range(2, prime - 1):
            yield prime, r

    for prime in prime_list:
        for r in range(prime + 1, p):
            if prime % r == 0 and r**2 > prime:
                yield prime, r
                break

    # Check all numbers from 2 to p-2
    for r in range(2, p):
        if r**2 <= p:
            if solve_hashing_problem(w1, w2, n, p, r):
                return prime, r

def power(x, r, p):
    result = 1
    mult = 1
    for _ in range(r):
        result = (result * x) % p
    return result

def solve_hashing_problem(w1, w2, n, p, r):
    H_w1 = 0
    H_w2 = 0

    for i in range(n):
        H_w1 = 26 + (H_w1 * 26 + ord(w1[i]) - ord('a')) % p
        H_w2 = 26 + (H_w2 * 26 + ord(w2[i]) - ord('a')) % p

    return H_w1 == H_w2

