    memo = {}

    def dp(idx):
        if idx == n:
            return 0
        if idx in memo:
            return memo[idx]
        # Limit max to prevent recursion depth error on large data
        max_val = max(contribs)
        choices = [min(1000000, idx*5) if contribs[idx] == max_val else int((contribs[idx] / (idx * 5 - 1)) * (idx*c + b)) + b]
        choices.extend([x + dp(i) for i, x in enumerate(choices) if i != idx])
