from math import isqrt, gcd
from functools import reduce

def extended_gcd(a, b):
    """Compute the extended Euclidean algorithm."""
    if a == 0:
        return (b, 0, 1)
    else:
        g, x, y = extended_gcd(b % a, a)
        return (g, y - (b // a) * x, x)

def lcm(a, b):
    """Compute the least common multiple of a and b."""
    return a * b // gcd(a, b)

def nth_perfect_lcm(n):
    """Find the nth perfect least common multiple."""
    a = 1
    for _ in range(n):
        # Find the smallest number x with a <= x <= 2 * a, resulting in the nth perfect LCM
        a += (2 * a < 2 * n) * (2 * n - a)
    return a

def main():
    n = int(input())
    primes = sorted(map(int, input().split()))
    k = int(input())

    # Compute the nth perfect least common multiple
    nth_lcm = nth_perfect_lcm(k)

    # Reduce all numbers in primes up to nth_lcm to find the k-th smallest number
    result = 1
    for prime in primes:
        result *= nth_lcm // prime

    print(result)

