def is_palindrome(s):
    return s == s[::-1]

def has_palindromic_path(graph, start, end):
    visited = [False] * (len(graph) + 1)
    path_sum = [0] * (1 << (len(graph)))

    def dfs(prev, path_sum, visited):
        if not visited[path_sum]:
            if path_sum & (1 << start) and is_palindrome(graph[start][prev]):
                path_sum |= 1 << start
                for i in range(1, len(graph)):
                    if not visited[i] and has_palindromic_path(graph, start, i):
                        dfs(i, path_sum, visited)
                    visited[i] = True
        return path_sum & ((1 << len(graph)) - 1)

    return dfs(start, path_sum[0], visited)

def solve(n, edges, k):
